/* ===== hotfix-v171.js ===== */
/* GRID SHIFT v1.7.1 — unified success feedback language.
   - GRAVITY keeps its dedicated cinematic chain system untouched.
   - Other modes use achievement-scaled visual/audio rewards.
   - Old generic MULTI/SQUARE labels are suppressed while the new reward is active.
   - Non-GRAVITY tray-to-tray CHAIN terminology becomes STREAK.
*/
(function(){
  'use strict';

  const VERSION=171;
  const previousBurstCells=burstCells;
  const previousClearBombsAt=clearBombsAt;
  const previousAnnounce=announce;

  let rewardSerial=0;
  let rewardTimer=0;
  let pendingBombReward=null;
  let bombDominatesUntil=0;

  function isGravity(){return state?.mode==='GRAVITY';}
  function modeClass(mode){return String(mode||'CLASSIC').toLowerCase();}

  function lineUnits(cells,size){
    if(!Array.isArray(cells)||!cells.length)return 0;
    const set=new Set(cells.map(([x,y])=>`${x},${y}`));
    let n=0;
    for(let y=0;y<size;y++){
      let full=true;
      for(let x=0;x<size;x++)if(!set.has(`${x},${y}`)){full=false;break;}
      if(full)n++;
    }
    for(let x=0;x<size;x++){
      let full=true;
      for(let y=0;y<size;y++)if(!set.has(`${x},${y}`)){full=false;break;}
      if(full)n++;
    }
    return n;
  }

  function squareInfo(cells,size){
    if(!Array.isArray(cells)||!cells.length)return {count:0,maxSide:0};
    const set=new Set(cells.map(([x,y])=>`${x},${y}`));
    const accepted=[];
    const full=(x,y,side)=>{
      for(let yy=y;yy<y+side;yy++)for(let xx=x;xx<x+side;xx++)if(!set.has(`${xx},${yy}`))return false;
      return true;
    };
    for(let side=size;side>=4;side--){
      for(let y=0;y<=size-side;y++)for(let x=0;x<=size-side;x++){
        if(!full(x,y,side))continue;
        const contained=accepted.some(s=>x>=s.x&&y>=s.y&&x+side<=s.x+s.side&&y+side<=s.y+s.side);
        if(!contained)accepted.push({x,y,side});
      }
    }
    return {count:accepted.length,maxSide:accepted.reduce((m,s)=>Math.max(m,s.side),0)};
  }

  function rewardLife(tier){return tier>=4?1500:tier===3?1250:1050;}

  function clearRewardLayer(){
    clearTimeout(rewardTimer);
    boardEl?.querySelectorAll('.reward-layer-v171').forEach(el=>el.remove());
    boardEl?.classList.remove('reward-active-v171','reward-tier-2-v171','reward-tier-3-v171','reward-tier-4-v171');
  }

  function rewardSound(mode,tier,kind='clear'){
    unlockAudio().then(ok=>{
      if(!ok)return;
      const t=Math.max(2,Math.min(4,tier||2));
      const power=(t-1)/3;

      if(kind==='bomb'){
        noiseBurst(.12+power*.08,.046+power*.018,1550+t*260);
        tone(58,.34+power*.16,'sawtooth',.052+power*.012,0,42);
        tone(116,.24,'triangle',.042,.025,82);
        tone(232,.22,'triangle',.032,.09);
        if(t>=3){tone(348,.24,'sine',.026,.17);tone(464,.30,'sine',.021,.25);}
        if(t>=4){noiseBurst(.16,.038,6200,.10);tone(696,.34,'sine',.018,.36);}
        haptic(t>=4?[28,20,34,18,42]:t===3?[23,18,30]:[18,24]);
        return;
      }

      if(kind==='stable'){
        noiseBurst(.045,.020,4800);
        tone(392,.18,'triangle',.034,0);
        tone(493.88,.22,'triangle',.031,.055);
        tone(587.33,.26,'sine',.028,.12);
        tone(783.99,.34,'sine',.021,.22);
        haptic([16,18,24]);
        return;
      }

      if(kind==='streak'){
        const root=t>=4?523.25:t===3?493.88:440;
        tone(root,.15,'triangle',.030,0);
        tone(root*1.25,.18,'sine',.026,.07);
        tone(root*1.5,.22,'sine',.024,.14);
        tone(root*2,.30,'sine',.018,.23);
        haptic(t>=4?[18,18,26]:[13,18]);
        return;
      }

      if(mode==='SQUARES'){
        const root=t>=4?440:t===3?392:349.23;
        noiseBurst(.050+power*.025,.020+power*.006,4700);
        tone(root,.22,'triangle',.036+power*.006,0);
        tone(root*1.25,.26,'triangle',.031,.06);
        tone(root*1.5,.30,'sine',.027,.13);
        tone(root*2,.36,'sine',.021,.22);
        if(t>=3)tone(root*2.5,.34,'sine',.017,.32);
        if(t>=4)tone(root*3,.42,'sine',.014,.42);
      }else if(mode==='BLITZ'){
        const root=t>=4?587.33:t===3?523.25:466.16;
        noiseBurst(.055+power*.025,.023+power*.006,5600+t*300);
        tone(root,.13,'sawtooth',.030+power*.006,0,root*1.18);
        tone(root*1.5,.17,'triangle',.027,.055);
        tone(root*2,.22,'sine',.022,.12);
        if(t>=3){tone(root*2.5,.20,'sine',.017,.20);tone(root*3,.27,'sine',.014,.28);}
      }else if(mode==='SHIFT'){
        const root=t>=4?493.88:t===3?440:392;
        noiseBurst(.042,.018+power*.004,4200);
        tone(root,.16,'triangle',.030+power*.006,0);
        tone(root*1.25,.19,'sine',.027,.06);
        tone(root*1.5,.24,'sine',.024,.13);
        if(t>=3)tone(root*2,.30,'sine',.018,.23);
      }else{
        const root=t>=4?523.25:t===3?466.16:415.30;
        noiseBurst(.045+power*.028,.020+power*.007,4500+t*220);
        tone(root,.15,'triangle',.031+power*.006,0);
        tone(root*1.25,.19,'triangle',.027,.055);
        tone(root*1.5,.23,'sine',.023,.12);
        if(t>=3)tone(root*2,.29,'sine',.018,.21);
        if(t>=4)tone(root*2.5,.36,'sine',.015,.31);
      }
      haptic(t>=4?[20,17,26,17,32]:t===3?[17,20,25]:[13,18]);
    });
  }

  function showReward({label,sub='',tier=2,mode=state?.mode||'CLASSIC',kind='clear'}){
    if(!boardEl||isGravity())return;
    clearRewardLayer();
    const serial=++rewardSerial;
    const t=Math.max(2,Math.min(4,tier));
    const life=rewardLife(t);

    boardEl.classList.add('reward-active-v171',`reward-tier-${t}-v171`);

    const layer=document.createElement('div');
    layer.className=`reward-layer-v171 mode-${modeClass(mode)}-v171 tier-${t}-v171 kind-${kind}-v171`;
    layer.style.setProperty('--reward-life-v171',`${life}ms`);

    const flash=document.createElement('i');flash.className='reward-flash-v171';layer.appendChild(flash);
    const ringCount=t>=4?4:t===3?3:2;
    for(let i=0;i<ringCount;i++){
      const ring=document.createElement('i');ring.className='reward-ring-v171';
      ring.style.setProperty('--reward-ring-delay-v171',`${i*80}ms`);
      ring.style.setProperty('--reward-ring-size-v171',`${26+i*17}%`);
      layer.appendChild(ring);
    }

    const copy=document.createElement('div');copy.className='reward-copy-v171';
    const main=document.createElement('b');main.textContent=label;copy.appendChild(main);
    if(sub){const small=document.createElement('span');small.textContent=sub;copy.appendChild(small);}
    layer.appendChild(copy);

    const sparks=t>=4?28:t===3?20:13;
    for(let i=0;i<sparks;i++){
      const p=document.createElement('i');p.className='reward-spark-v171';
      p.style.setProperty('--reward-a-v171',`${i*(360/sparks)+(i%2?5:0)}deg`);
      p.style.setProperty('--reward-d-v171',`${74+t*24+(i%4)*11}px`);
      p.style.setProperty('--reward-delay-v171',`${(i%7)*18}ms`);
      layer.appendChild(p);
    }

    boardEl.appendChild(layer);
    rewardSound(mode,t,kind);
    rewardTimer=setTimeout(()=>{
      if(serial!==rewardSerial)return;
      layer.remove();
      boardEl.classList.remove('reward-active-v171',`reward-tier-${t}-v171`);
    },life+80);
  }

  function rewardForClear(cells){
    if(!state||isGravity()||!Array.isArray(cells)||!cells.length)return;
    const mode=state.mode;

    if(mode==='BOMBS'&&pendingBombReward){
      const b=pendingBombReward;pendingBombReward=null;
      bombDominatesUntil=performance.now()+420;
      const tier=b.count>=3?4:b.count>=2?3:2;
      showReward({
        label:b.count>=2?`BOMB CHAIN ${b.count}`:'BOMB BLAST',
        sub:b.count>=2?'CHAIN REACTION':'3×3 BLAST',
        tier,mode,kind:'bomb'
      });
      return;
    }

    if(mode==='BOMBS'&&performance.now()<bombDominatesUntil)return;

    if(mode==='SQUARES'){
      const info=squareInfo(cells,state.size);
      if(!info.count)return;
      const tier=(info.maxSide>=6||info.count>=3)?4:(info.maxSide>=5||info.count>=2)?3:2;
      if(info.count>=2){
        showReward({label:`${info.count} SQUARES`,sub:`MAX ${info.maxSide}×${info.maxSide}`,tier,mode});
      }else{
        showReward({label:`${info.maxSide}×${info.maxSide}`,sub:'SQUARE',tier,mode});
      }
      return;
    }

    const units=lineUnits(cells,state.size);
    if(units<2)return; // one clear already has strong short-form juice in v1.3.3
    const tier=units>=4?4:units===3?3:2;
    const sub=mode==='BLITZ'?'RUSH CLEAR':mode==='SHIFT'?'LINE CLEAR':mode==='BOMBS'?'LINE CLEAR':'MULTI LINE';
    showReward({label:`${units} CLEAR`,sub,tier,mode});
  }

  clearBombsAt=function(cells){
    if(state?.mode!=='BOMBS')return previousClearBombsAt(cells);
    const before=Array.isArray(state.bombs)?state.bombs.length:0;
    const out=previousClearBombsAt(cells);
    const after=Array.isArray(state.bombs)?state.bombs.length:0;
    const n=Math.max(0,before-after);
    if(n>0){
      pendingBombReward={count:n,gain:Number(state.bombLastBlast?.gain)||0};
    }
    return out;
  };

  burstCells=function(cells,wave=0){
    if(!isGravity()){
      try{rewardForClear(cells);}catch(_){ }
    }
    return previousBurstCells(cells,wave);
  };

  announce=function(text,strong=false){
    let next=String(text??'');
    if(!isGravity()&&/^CHAIN\s+\d+/i.test(next))next=next.replace(/^CHAIN/i,'STREAK');
    const out=previousAnnounce(next,strong);

    if(state?.mode==='SHIFT'&&/^STABLE\b/i.test(next)){
      setTimeout(()=>showReward({label:'STABLE',sub:'NO SHIFT',tier:3,mode:'SHIFT',kind:'stable'}),70);
    }else if(!isGravity()&&/^STREAK\s+(\d+)/i.test(next)){
      const m=next.match(/^STREAK\s+(\d+)/i),n=Number(m?.[1])||0;
      const tier=n>=10?4:n>=5?3:2;
      setTimeout(()=>showReward({label:`STREAK ${n}`,sub:'KEEP IT GOING',tier,mode:state?.mode||'CLASSIC',kind:'streak'}),520);
    }
    return out;
  };

  queueMicrotask(()=>{
    try{if(state)state.rewardFeedbackVersionV171=VERSION;}catch(_){ }
  });
})();


/* ===== hotfix-v172.js ===== */
/* GRID SHIFT v1.7.2 — SQUARES becomes PERFECT SQUARES.
   A clear happens only when an entire orthogonally-connected occupied component
   is itself a completely filled 4x4+ square. Any edge-connected protrusion blocks
   the clear, so players can deliberately keep a tail to grow toward 5x5...10x10.
   Piece generation stays fair but not deterministic: precision help rises only
   under pressure, preserving the skill/luck tension. */
(function(){
  'use strict';

  const VERSION=172;
  const previousScanClears=Core.scanClears;
  const previousSimulatePlace=Core.simulatePlace;
  const previousGenerateFairTray=Core.generateFairTray;
  const previousTryPlace=tryPlace;
  const previousScoreClear=scoreClear;
  const previousUpdatePreview=updatePreview;
  const previousClearPreview=clearPreview;
  const previousRenderModeStat=renderModeStat;
  const previousModeDemoHTML=modeDemoHTML;
  const previousBurstCells=burstCells;

  const SCORE_BY_SIDE={4:200,5:450,6:900,7:1700,8:3000,9:5200,10:9000};
  let squareScoreContext=null;
  let apexSerial=0;
  let apexTimer=0;

  function occupiedComponents(board,size){
    const seen=new Set(),out=[];
    for(let y=0;y<size;y++)for(let x=0;x<size;x++){
      if(!board[y][x])continue;
      const first=`${x},${y}`;
      if(seen.has(first))continue;
      const q=[[x,y]],cells=[];seen.add(first);
      let minX=x,maxX=x,minY=y,maxY=y;
      while(q.length){
        const [cx,cy]=q.pop();cells.push([cx,cy]);
        minX=Math.min(minX,cx);maxX=Math.max(maxX,cx);minY=Math.min(minY,cy);maxY=Math.max(maxY,cy);
        for(const [nx,ny] of [[cx+1,cy],[cx-1,cy],[cx,cy+1],[cx,cy-1]]){
          const k=`${nx},${ny}`;
          if(nx>=0&&ny>=0&&nx<size&&ny<size&&board[ny][nx]&&!seen.has(k)){
            seen.add(k);q.push([nx,ny]);
          }
        }
      }
      out.push({cells,minX,maxX,minY,maxY,w:maxX-minX+1,h:maxY-minY+1});
    }
    return out;
  }

  function scanPerfectSquares(board,size){
    const squares=[],cells=[];
    for(const comp of occupiedComponents(board,size)){
      if(comp.w!==comp.h||comp.w<4)continue;
      const side=comp.w;
      if(comp.cells.length!==side*side)continue;
      squares.push([comp.minX,comp.minY,side]);
      cells.push(...comp.cells);
    }
    return {rows:[],cols:[],squares,units:squares.length,cells};
  }

  Core.scanClears=function(board,size,mode){
    if(mode==='SQUARES')return scanPerfectSquares(board,size);
    return previousScanClears(board,size,mode);
  };

  Core.simulatePlace=function(board,shape,x,y,mode,size){
    if(mode!=='SQUARES')return previousSimulatePlace(board,shape,x,y,mode,size);
    if(!Core.canPlace(board,shape,x,y,size))return null;
    const next=Core.cloneBoard(board);
    const placed=shape.cells.map(([dx,dy],i)=>[x+dx,y+dy,shape.cellColors?.[i]||shape.color||1]);
    placed.forEach(([xx,yy,color])=>next[yy][xx]=color);
    const clear=scanPerfectSquares(next,size),waves=[];
    if(clear.units){waves.push(clear);Core.clearCells(next,clear.cells);}
    return {board:next,placed:placed.map(([px,py])=>[px,py]),waves,stages:[]};
  };

  function boardPressure(board,size){
    const fill=Core.boardFill(board),comps=occupiedComponents(board,size);
    let largestSpan=0,largestCells=0,nearMissing=99;
    for(const c of comps){
      const side=Math.max(c.w,c.h);
      largestSpan=Math.max(largestSpan,side);
      largestCells=Math.max(largestCells,c.cells.length);
      if(side>=4){
        const missing=side*side-c.cells.length;
        if(missing>=0)nearMissing=Math.min(nearMissing,missing);
      }
    }
    return {fill,largestSpan,largestCells,nearMissing};
  }

  function weightedShape(pool,rng){
    let total=0;for(const [,w] of pool)total+=w;
    let n=rng()*total,id=pool[0][0];
    for(const [candidate,w] of pool){n-=w;if(n<0){id=candidate;break;}}
    let s=Core.deepClone(Core.SHAPE_BY_ID[id]);
    const turns=Math.floor(rng()*4);for(let i=0;i<turns;i++)s=Core.rotateShape(s);
    return s;
  }

  function squarePool(board,size){
    const p=boardPressure(board,size);
    const pool=[
      ['sq2',11],['i3h',10],['l3a',9],['i4h',8],['l4a',7],
      ['t4u',5],['rect6',4],['z4h',3],['i5h',3],['sq3',1],['plus5',1]
    ];

    /* Larger projects benefit from controllable edges, but we never hand over
       the exact missing piece deterministically. */
    if(p.largestSpan>=6){pool.push(['i3h',3],['l3a',3],['sq2',3],['i4h',2]);}
    if(p.largestSpan>=8){pool.push(['i3h',2],['i4h',2],['l4a',2]);}

    /* Precision pieces are a pressure valve, not the normal strategy. */
    if(p.fill>=54)pool.push(['i2h',1]);
    if(p.fill>=66)pool.push(['i2h',2]);
    if(p.fill>=76)pool.push(['i2h',2],['dot',1]);
    if(p.nearMissing<=4&&p.fill>=48)pool.push(['i2h',2]);
    if(p.nearMissing<=2&&p.fill>=62)pool.push(['dot',1]);
    return {pool,pressure:p};
  }

  function generatePerfectSquareTray(board,size,rng=Math.random,moves=0){
    const {pool,pressure}=squarePool(board,size);
    let fallback=null;
    for(let attempt=0;attempt<30;attempt++){
      const tray=[weightedShape(pool,rng),weightedShape(pool,rng),weightedShape(pool,rng)];
      const tiny=tray.filter(p=>p.cells.length<=2).length;
      if(tiny>1)continue;
      if(pressure.fill<54&&tiny>0)continue;
      if(!tray.every(p=>Core.hasModePlacement(board,p,size,'SQUARES')))continue;
      fallback=fallback||tray;
      if(Core.trayHasSolution(board,tray,'SQUARES',size,9500))return tray;
    }
    if(fallback)return fallback;
    /* v1.3.0's generator now runs through the new exact-square simulator, so it
       remains a reliable last-resort fair-tray search without guaranteeing a win. */
    return previousGenerateFairTray(board,'SQUARES',size,rng,moves);
  }

  Core.generateFairTray=function(board,mode,size,rng=Math.random,moves=0){
    if(mode==='SQUARES')return generatePerfectSquareTray(board,size,rng,moves);
    return previousGenerateFairTray(board,mode,size,rng,moves);
  };

  function squareSidesFromWave(wave){
    return Array.isArray(wave?.squares)?wave.squares.map(s=>Number(s?.[2])||0).filter(n=>n>=4):[];
  }

  scoreClear=function(units,cells,cascade){
    if(state?.mode!=='SQUARES'||!squareScoreContext?.length)return previousScoreClear(units,cells,cascade);
    const sides=squareScoreContext;
    let base=sides.reduce((sum,side)=>sum+(SCORE_BY_SIDE[side]||Math.round(side*side*12)),0);
    if(sides.length>1)base=Math.round(base*(1+(sides.length-1)*.25));
    const streakMult=1+Math.min(Number(state.chain)||0,12)*.06;
    return Math.round(base*streakMult);
  };

  tryPlace=function(idx,x,y){
    if(state?.mode!=='SQUARES')return previousTryPlace(idx,x,y);
    const shape=state.tray?.[idx];
    let sim=null;
    if(shape&&Core.canPlace(state.board,shape,x,y,state.size))sim=Core.simulatePlace(state.board,shape,x,y,'SQUARES',state.size);
    squareScoreContext=squareSidesFromWave(sim?.waves?.[0]);
    const maxSide=squareScoreContext.length?Math.max(...squareScoreContext):0;
    try{
      const ok=previousTryPlace(idx,x,y);
      if(ok&&maxSide>=4){
        state.squaresBestPerfectV172=Math.max(Number(state.squaresBestPerfectV172)||0,maxSide);
        state.squaresRulesVersionV172=VERSION;
        scheduleSave();
      }
      return ok;
    }finally{
      squareScoreContext=null;
    }
  };

  function removeFinishPreview(){
    boardEl?.querySelectorAll('.square-finish-preview-v172').forEach(el=>el.remove());
  }

  function addFinishPreview(square){
    const [x,y,side]=square;
    const a=cellEls[y]?.[x],z=cellEls[y+side-1]?.[x+side-1];
    if(!a||!z)return;
    const e=document.createElement('i');e.className='square-finish-preview-v172';
    e.style.left=`${a.offsetLeft-2}px`;e.style.top=`${a.offsetTop-2}px`;
    e.style.width=`${z.offsetLeft+z.offsetWidth-a.offsetLeft+4}px`;
    e.style.height=`${z.offsetTop+z.offsetHeight-a.offsetTop+4}px`;
    e.dataset.side=String(side);
    boardEl.appendChild(e);
  }

  clearPreview=function(){
    removeFinishPreview();
    return previousClearPreview();
  };

  updatePreview=function(){
    const out=previousUpdatePreview();
    removeFinishPreview();
    if(state?.mode!=='SQUARES'||selectedPiece===null||!previewAnchor)return out;
    const shape=drag?.shape||state.tray?.[selectedPiece];
    if(!shape||!Core.canPlace(state.board,shape,previewAnchor.x,previewAnchor.y,state.size))return out;
    const sim=Core.simulatePlace(state.board,shape,previewAnchor.x,previewAnchor.y,'SQUARES',state.size);
    const squares=sim?.waves?.[0]?.squares||[];
    if(!squares.length)return out;

    /* The player gets confirmation only at the exact finishing move, not a
       persistent construction hint. */
    boardEl.querySelectorAll('.preview-clear').forEach(c=>c.classList.remove('preview-clear'));
    squares.forEach(addFinishPreview);
    return out;
  };

  renderModeStat=function(){
    const out=previousRenderModeStat();
    if(state?.mode==='SQUARES'){
      const best=Number(state.squaresBestPerfectV172)||0;
      modeStatEl.textContent=best>=4?`BEST ${best}×${best}`:'PERFECT 4×4+';
      modeStatEl.classList.add('visible');
    }
    return out;
  };

  function squaresFromCells(cells,size){
    if(!Array.isArray(cells)||!cells.length)return [];
    const board=Core.emptyBoard(size);
    for(const [x,y] of cells)if(x>=0&&y>=0&&x<size&&y<size)board[y][x]=1;
    return scanPerfectSquares(board,size).squares;
  }

  function apexSound(side){
    unlockAudio().then(ok=>{
      if(!ok)return;
      const level=Math.max(0,Math.min(3,side-7));
      const root=[392,440,493.88,523.25][level];
      const p=(side-6)/4;
      noiseBurst(.15+p*.08,.038+p*.014,2100+side*180);
      tone(46+side*2,.52+p*.18,'sawtooth',.052+p*.012,0,72+side*3);
      tone(root*.5,.40,'triangle',.038,.06,root*.72);
      const arp=[1,1.25,1.5,2,2.5,3];
      arp.slice(0,side===10?6:side===9?5:4).forEach((m,i)=>tone(root*m,.20+i*.035,'sine',.024,.22+i*.11));
      const d=side===10?1.15:side===9?.92:.76;
      tone(root,.48,'triangle',.041,d);
      tone(root*1.5,.56,'sine',.036,d+.08);
      tone(root*2,.66,'sine',.030,d+.17);
      if(side>=9)tone(root*2.5,.72,'sine',.023,d+.29);
      if(side===10){
        noiseBurst(.20,.035,6800,.44);
        tone(root*3,.84,'sine',.019,d+.42);
        tone(root*4,1.02,'sine',.014,d+.56);
      }
      haptic(side===10?[34,22,38,22,48,28,62]:side===9?[28,20,34,20,46]:[22,18,30,18,36]);
    });
  }

  function showApex(square){
    if(!boardEl||!square)return;
    clearTimeout(apexTimer);
    const side=Number(square[2])||7,serial=++apexSerial;
    boardEl.querySelectorAll('.square-apex-layer-v172').forEach(el=>el.remove());
    boardEl.classList.add('square-apex-active-v172',`square-apex-${side}-v172`);

    const life=side===10?3500:side===9?2850:side===8?2350:1950;
    const layer=document.createElement('div');
    layer.className=`square-apex-layer-v172 side-${side}-v172`;
    layer.style.setProperty('--square-apex-life-v172',`${life}ms`);

    const wash=document.createElement('i');wash.className='square-apex-wash-v172';layer.appendChild(wash);
    for(let i=0;i<(side===10?6:side===9?5:4);i++){
      const ring=document.createElement('i');ring.className='square-apex-ring-v172';
      ring.style.setProperty('--sq-ring-delay-v172',`${i*105}ms`);
      ring.style.setProperty('--sq-ring-size-v172',`${24+i*14}%`);
      layer.appendChild(ring);
    }

    const copy=document.createElement('div');copy.className='square-apex-copy-v172';
    const over=document.createElement('span');over.textContent='PERFECT';
    const main=document.createElement('b');main.textContent=`${side}×${side}`;
    const sub=document.createElement('em');sub.textContent=side===10?'FULL BOARD':side>=9?'MASTER SQUARE':'PERFECT SQUARE';
    copy.append(over,main,sub);layer.appendChild(copy);

    const sparks=side===10?54:side===9?42:side===8?34:28;
    for(let i=0;i<sparks;i++){
      const p=document.createElement('i');p.className='square-apex-spark-v172';
      p.style.setProperty('--sq-a-v172',`${i*(360/sparks)+(i%2?4:0)}deg`);
      p.style.setProperty('--sq-d-v172',`${120+(side-7)*26+(i%5)*13}px`);
      p.style.setProperty('--sq-delay-v172',`${(i%9)*24}ms`);
      layer.appendChild(p);
    }

    boardEl.appendChild(layer);
    apexSound(side);
    apexTimer=setTimeout(()=>{
      if(serial!==apexSerial)return;
      layer.remove();
      boardEl.classList.remove('square-apex-active-v172',`square-apex-${side}-v172`);
    },life+120);
  }

  burstCells=function(cells,wave=0){
    if(state?.mode==='SQUARES'){
      const squares=squaresFromCells(cells,state.size);
      const biggest=squares.sort((a,b)=>b[2]-a[2])[0];
      if(biggest?.[2]>=7){
        boardEl.classList.add('square-apex-active-v172');
        const out=previousBurstCells(cells,wave);
        requestAnimationFrame(()=>showApex(biggest));
        return out;
      }
    }
    return previousBurstCells(cells,wave);
  };

  modeDemoHTML=function(id){
    if(id!=='SQUARES')return previousModeDemoHTML(id);
    let cells='';
    for(let y=1;y<=4;y++)for(let x=0;x<4;x++)cells+=miniCell(x,y,'md-gold md-sq v172-perfect-cell');
    return `<div class="mode-demo demo-squares demo-squares-v172"><div class="mini-board">${cells}<i class="square-outline square-outline-v172"></i><b class="v172-perfect-tag">PERFECT</b></div></div>`;
  };

  queueMicrotask(()=>{
    try{
      if(state?.mode==='SQUARES'){
        state.squaresRulesVersionV172=VERSION;
        renderAll();scheduleSave(true);
      }
      buildMenu();renderMenu();
    }catch(_){ }
  });
})();


/* ===== hotfix-v172-fair.js ===== */
/* GRID SHIFT v1.7.2 — PERFECT SQUARES fair-tray solver correction.
   script2's exported trayHasSolution closes over the original simulator, so
   SQUARES needs a solver that calls the live Core.simulatePlace override. */
(function(){
  'use strict';

  const previousGenerate=Core.generateFairTray;

  function components(board,size){
    const seen=new Set(),out=[];
    for(let y=0;y<size;y++)for(let x=0;x<size;x++){
      if(!board[y][x]||seen.has(`${x},${y}`))continue;
      const q=[[x,y]],cells=[];seen.add(`${x},${y}`);
      let minX=x,maxX=x,minY=y,maxY=y;
      while(q.length){
        const [cx,cy]=q.pop();cells.push([cx,cy]);
        minX=Math.min(minX,cx);maxX=Math.max(maxX,cx);minY=Math.min(minY,cy);maxY=Math.max(maxY,cy);
        for(const [nx,ny] of [[cx+1,cy],[cx-1,cy],[cx,cy+1],[cx,cy-1]]){
          const k=`${nx},${ny}`;
          if(nx>=0&&ny>=0&&nx<size&&ny<size&&board[ny][nx]&&!seen.has(k)){seen.add(k);q.push([nx,ny]);}
        }
      }
      out.push({cells,w:maxX-minX+1,h:maxY-minY+1});
    }
    return out;
  }

  function pressure(board,size){
    const fill=Core.boardFill(board),cs=components(board,size);
    let span=0,near=99;
    for(const c of cs){
      const side=Math.max(c.w,c.h);span=Math.max(span,side);
      if(side>=4)near=Math.min(near,Math.max(0,side*side-c.cells.length));
    }
    return {fill,span,near};
  }

  function pick(pool,rng){
    let total=0;for(const [,w] of pool)total+=w;
    let n=rng()*total,id=pool[0][0];
    for(const [candidate,w] of pool){n-=w;if(n<0){id=candidate;break;}}
    let s=Core.deepClone(Core.SHAPE_BY_ID[id]);
    for(let i=0,nTurns=Math.floor(rng()*4);i<nTurns;i++)s=Core.rotateShape(s);
    return s;
  }

  function solvable(board,tray,size,maxNodes=10500){
    let nodes=0;
    function dfs(b,remaining){
      if(!remaining.length)return true;
      if(++nodes>maxNodes)return false;
      const ordered=remaining.slice().sort((a,bx)=>tray[bx].cells.length-tray[a].cells.length);
      for(const idx of ordered){
        for(const shape of Core.modeRotations(tray[idx],'SQUARES')){
          const ps=Core.placements(b,shape,size),step=ps.length>48?Math.ceil(ps.length/48):1;
          for(let i=0;i<ps.length;i+=step){
            const [x,y]=ps[i],sim=Core.simulatePlace(b,shape,x,y,'SQUARES',size);
            if(!sim)continue;
            if(dfs(sim.board,remaining.filter(v=>v!==idx)))return true;
            if(nodes>maxNodes)return false;
          }
        }
      }
      return false;
    }
    return dfs(Core.cloneBoard(board),tray.map((_,i)=>i));
  }

  function normalPool(p){
    const pool=[['sq2',11],['i3h',10],['l3a',9],['i4h',8],['l4a',7],['t4u',5],['rect6',4],['z4h',3],['i5h',3],['sq3',1],['plus5',1]];
    if(p.span>=6)pool.push(['i3h',3],['l3a',3],['sq2',3],['i4h',2]);
    if(p.span>=8)pool.push(['i3h',2],['i4h',2],['l4a',2]);
    if(p.fill>=54)pool.push(['i2h',1]);
    if(p.fill>=66)pool.push(['i2h',2]);
    if(p.fill>=76)pool.push(['i2h',2],['dot',1]);
    if(p.near<=4&&p.fill>=48)pool.push(['i2h',2]);
    if(p.near<=2&&p.fill>=62)pool.push(['dot',1]);
    return pool;
  }

  function generate(board,size,rng=Math.random){
    const p=pressure(board,size),pool=normalPool(p);
    for(let attempt=0;attempt<34;attempt++){
      const tray=[pick(pool,rng),pick(pool,rng),pick(pool,rng)];
      const tiny=tray.filter(s=>s.cells.length<=2).length;
      if(tiny>1||(p.fill<54&&tiny>0))continue;
      if(!tray.every(s=>Core.hasModePlacement(board,s,size,'SQUARES')))continue;
      if(solvable(board,tray,size))return tray;
    }

    /* Only when the field is genuinely tight do precision pieces become common.
       Even here the tray is selected from many valid candidates, not tailored to
       the exact winning hole, so luck remains part of a 7x7–10x10 attempt. */
    const emergency=[['i2h',7],['dot',2],['i3h',8],['l3a',7],['sq2',7],['i4h',5],['l4a',4]];
    for(let attempt=0;attempt<90;attempt++){
      const tray=[pick(emergency,rng),pick(emergency,rng),pick(emergency,rng)];
      if(tray.filter(s=>s.cells.length===1).length>1)continue;
      if(!tray.every(s=>Core.hasModePlacement(board,s,size,'SQUARES')))continue;
      if(solvable(board,tray,size,15000))return tray;
    }

    /* Let the earlier generator handle only the pathological last resort. */
    return previousGenerate(board,'SQUARES',size,rng,0);
  }

  Core.generateFairTray=function(board,mode,size,rng=Math.random,moves=0){
    if(mode==='SQUARES')return generate(board,size,rng);
    return previousGenerate(board,mode,size,rng,moves);
  };
})();


/* ===== hotfix-v176.js ===== */
/* GRID SHIFT v1.7.6 — settle tray geometry after asynchronous refill/layout.
   iPhone Safari can report an unstable tray slot size on the first paint after a
   three-piece refill (especially BOMBS with disabled support pieces). v1.6.4
   already fixes the geometry when measurements are ready; this pass repeats that
   same authoritative positioning across the next few layout opportunities without
   rebuilding the tray or changing gameplay. */
(function(){
  'use strict';

  const previousRenderTray=renderTray;
  let repairSerial=0;
  let repairTimers=[];

  function geometry(shape){
    const [w,h]=Core.shapeDims(shape);
    const u=trayUnit(shape),g=4;
    return {width:w*u+(w-1)*g,height:h*u+(h-1)*g};
  }

  function repairOne(wrap,shape){
    if(!wrap||!shape)return false;
    const art=wrap.querySelector(':scope > .piece-art.tray');
    const rot=wrap.querySelector(':scope > .rotate-affordance');
    const ww=wrap.clientWidth,wh=wrap.clientHeight;
    if(!ww||!wh)return false;

    const geo=geometry(shape);
    wrap.style.setProperty('position','relative','important');

    if(art){
      art.classList.add('tray-art-v164');
      art.style.setProperty('width',`${geo.width}px`,'important');
      art.style.setProperty('height',`${geo.height}px`,'important');
      art.style.setProperty('display','block','important');
      art.style.setProperty('position','absolute','important');
      art.style.setProperty('left',`${(ww-geo.width)/2}px`,'important');
      art.style.setProperty('top',`${(wh-geo.height)/2}px`,'important');
      art.style.setProperty('right','auto','important');
      art.style.setProperty('bottom','auto','important');
      art.style.setProperty('margin','0','important');
      art.style.setProperty('translate','none','important');
      art.style.setProperty('grid-template-columns','none','important');
      art.style.setProperty('grid-template-rows','none','important');
      art.style.setProperty('align-items','initial','important');
      art.style.setProperty('justify-items','initial','important');
    }

    if(rot){
      const rw=rot.offsetWidth||70,rh=rot.offsetHeight||70;
      rot.style.setProperty('position','absolute','important');
      rot.style.setProperty('left',`${(ww-rw)/2}px`,'important');
      rot.style.setProperty('top',`${(wh-rh)/2}px`,'important');
      rot.style.setProperty('right','auto','important');
      rot.style.setProperty('bottom','auto','important');
      rot.style.setProperty('margin','0','important');
      rot.style.setProperty('translate','none','important');
    }
    return true;
  }

  function repairNow(token){
    if(token!==repairSerial||!trayEl||!state?.tray)return;
    trayEl.querySelectorAll(':scope > .piece-wrap').forEach(wrap=>{
      const idx=Number(wrap.dataset.idx);
      const shape=state.tray[idx];
      if(shape)repairOne(wrap,shape);
    });
  }

  function scheduleRepairs(){
    const token=++repairSerial;
    repairTimers.forEach(clearTimeout);repairTimers=[];

    requestAnimationFrame(()=>{
      repairNow(token);
      requestAnimationFrame(()=>repairNow(token));
    });

    for(const delay of [48,120,260]){
      repairTimers.push(setTimeout(()=>repairNow(token),delay));
    }
  }

  renderTray=function(){
    const out=previousRenderTray();
    scheduleRepairs();
    return out;
  };

  /* A tray refill replaces all three children at once. Observe that exact DOM
     event so Safari gets another geometry pass even when no further game render
     occurs immediately afterwards. Styling changes made by repairNow are ignored. */
  const observer=new MutationObserver(records=>{
    if(records.some(r=>r.type==='childList'))scheduleRepairs();
  });
  observer.observe(trayEl,{childList:true});

  if(window.ResizeObserver){
    const ro=new ResizeObserver(()=>scheduleRepairs());
    ro.observe(trayEl);
  }

  window.addEventListener('pageshow',scheduleRepairs,{passive:true});
  window.addEventListener('resize',scheduleRepairs,{passive:true});
  window.addEventListener('orientationchange',()=>setTimeout(scheduleRepairs,120),{passive:true});

  queueMicrotask(scheduleRepairs);
})();


/* ===== hotfix-v177.js ===== */
/* GRID SHIFT v1.7.7 — suppress iOS selection/loupe gestures without blocking touch drag. */
(function(){
  'use strict';

  function inGameUi(target){
    return !!target?.closest?.('#app,.overlay');
  }

  /* Prevent text/image selection and long-press context UI. Intentionally do NOT
     prevent touchstart/touchmove/pointermove; those are required by the game. */
  document.addEventListener('selectstart',e=>{
    if(inGameUi(e.target))e.preventDefault();
  },true);
  document.addEventListener('contextmenu',e=>{
    if(inGameUi(e.target))e.preventDefault();
  },true);
  document.addEventListener('dragstart',e=>{
    if(inGameUi(e.target))e.preventDefault();
  },true);
})();

